"""Definitions copied from the verified v2 notebook; no training executes on import."""
import math
import numpy as np
import torch
import torch.nn as nn
import torch.nn.functional as F
from scipy.ndimage import gaussian_filter
from torch.utils.checkpoint import checkpoint

SOURCE = '# %% Earth-model generator (<= 4 layers, 4 km deep)\n# ======================================================================================\n# Synthetic layered Earth model generator  (4 km deep, 2-4 layers)\n# --------------------------------------------------------------------------------------\n# Design basis (see the markdown cell above for the full rationale + references):\n#   * "Layer-cake" sedimentary column: every layer = one lithology unit with its own\n#     top velocity V_top and compaction gradient k:   V(z) = V_top + k (z - z_top)\n#     (Slotnick 1936; the V0-k layer cake used for real basins, e.g. van Dalfsen et al. 2006)\n#   * V_top / k ranges per lithology from rock-velocity compilations\n#     (Telford et al. 1990; Sheriff & Geldart 1995; Lowrie 2007; Kearey et al. 2002)\n#   * Velocity generally increases with depth (compaction), small chance of an inversion\n#   * Conformable interfaces: regional dip + gentle folds (+ optional normal fault)\n# ======================================================================================\n# ---- design parameters (change here, everything else follows) -------------------------\nN_LAYERS_MIN, N_LAYERS_MAX = 2, 4     # senior\'s rule: never more than 4 layers\nMIN_THICK_1D = 300.0                  # m, minimum layer thickness in 1-D columns\nMIN_THICK_2D = 200.0                  # m, minimum thickness after lateral folding\nV_MIN, V_MAX = 1500.0, 6000.0         # m/s, hard limits of the whole model\nV_TOP_MAX = 5800.0                    # m/s, highest allowed layer-top velocity\nMIN_CONTRAST = 1.15                   # V_top(i+1) >= 1.15 * V_top(i)\nINTERFACE_GAP = 1.08                  # >= 8 % velocity jump across every (normal) interface\nINVERSION_PROB = 0.10                 # chance that two deep layers swap (low-velocity layer)\nFAULT_PROB = 0.25                     # chance of one normal fault in a 2-D model\nSALT_PROB = 0.0                       # salt body is OFF by default (it would be a 5th unit)\nSALT_VEL = 4500.0                     # m/s (rock salt 4500-5500, Telford/Sheriff)\n\n# lithology: (V_top low, V_top high, gradient low, gradient high, velocity cap)  [m/s, m/s per m]\nLITHOLOGY = {\n    "unconsolidated sand/clay":    (1500, 2000, 0.80, 1.50, 2800),\n    "shale / mudstone":            (2000, 3300, 0.30, 0.80, 4200),\n    "sandstone":                   (2400, 4000, 0.20, 0.60, 5000),\n    "limestone":                   (3300, 5200, 0.05, 0.30, 5800),\n    "dolomite":                    (4200, 5800, 0.05, 0.20, 6000),\n    "evaporite (anhydrite/salt)":  (4400, 5200, 0.00, 0.05, 5500),\n}\nLITH_NAMES = list(LITHOLOGY)\n# probability of each lithology (same order as LITHOLOGY) by position in the column\nPOS_WEIGHTS = {\n    "shallow": [0.45, 0.35, 0.20, 0.00, 0.00, 0.00],\n    "middle":  [0.00, 0.30, 0.30, 0.25, 0.05, 0.10],\n    "deep":    [0.00, 0.20, 0.25, 0.35, 0.10, 0.10],\n}\n\n\ndef sample_layer_column(rng, zmax=(NZ - 1) * DH, nl=None, min_thick=MIN_THICK_1D):\n    """Draw ONE 1-D layered column (2-4 layers). Used by both the 2-D models and the\n    time-depth data set, so both come from the same Earth model."""\n    nl = int(rng.integers(N_LAYERS_MIN, N_LAYERS_MAX + 1)) if nl is None else int(nl)\n    for _ in range(100):                                    # re-draw if velocities exceed V_TOP_MAX\n        names, vt, gr, lc = [], [], [], []\n        for i in range(nl):\n            pos = "shallow" if i == 0 else ("deep" if i == nl - 1 else "middle")\n            name = LITH_NAMES[rng.choice(len(LITH_NAMES), p=POS_WEIGHTS[pos])]\n            lo, hi, glo, ghi, cap = LITHOLOGY[name]\n            names.append(name); vt.append(rng.uniform(lo, hi))\n            gr.append(rng.uniform(glo, ghi)); lc.append(cap)\n        order = np.argsort(vt)                              # compaction: faster rock deeper\n        names = [names[i] for i in order]; vt = np.array(vt)[order]\n        gr = np.array(gr)[order]; lc = np.array(lc)[order]\n        for i in range(1, nl):                              # guarantee an impedance contrast\n            vt[i] = max(vt[i], vt[i - 1] * MIN_CONTRAST)\n        if vt[-1] <= V_TOP_MAX:\n            break\n    vt = np.minimum(vt, V_TOP_MAX)\n    if nl >= 3 and rng.random() < INVERSION_PROB:           # low-velocity layer below a fast one\n        j = int(rng.integers(1, nl - 1))\n        for a in (names, vt, gr, lc):\n            a[j], a[j + 1] = a[j + 1], a[j]\n    cap = np.empty(nl)\n    for i in range(nl):                                     # velocity ceiling inside layer i\n        c = max(lc[i], vt[i] * INTERFACE_GAP)\n        if i < nl - 1 and vt[i + 1] > vt[i]:\n            c = min(c, vt[i + 1] / INTERFACE_GAP)             # stay below the next layer\'s top\n        cap[i] = min(max(c, vt[i]), V_MAX)\n    w = rng.dirichlet(np.full(nl, 2.0))\n    thick = min_thick + (zmax - nl * min_thick) * w\n    return dict(nl=nl, tops=np.cumsum(thick)[:-1], vtop=np.asarray(vt), grad=np.asarray(gr),\n                cap=cap, lith=names, zmax=float(zmax))\n\n\ndef column_velocity(col, z):\n    """Instantaneous velocity V(z) of a 1-D column (m/s); z in metres (array or scalar)."""\n    z = np.asarray(z, dtype=float)\n    idx = np.searchsorted(col["tops"], z, side="right")\n    ztop = np.concatenate([[0.0], col["tops"]])[idx]\n    return np.minimum(col["vtop"][idx] + col["grad"][idx] * (z - ztop), col["cap"][idx])\n\n\ndef column_twt(col, z):\n    """Exact two-way time (seconds) from the surface to depth z (array or scalar).\n    Inside a gradient segment: t = (2/k) ln(1 + k d / V_start); constant segment: t = 2 d / V."""\n    z = np.asarray(z, dtype=float)\n    bounds = np.concatenate([[0.0], col["tops"], [col["zmax"]]])\n    t = np.zeros_like(z)\n    for i in range(col["nl"]):\n        z0, z1, v0, g, cap = bounds[i], bounds[i + 1], col["vtop"][i], col["grad"][i], col["cap"][i]\n        zc = min(z1, z0 + (cap - v0) / g) if (g > 1e-9 and cap > v0) else z0\n        segs = []\n        if zc > z0:\n            segs.append((z0, zc, v0, g))\n        if z1 > zc:\n            segs.append((zc, z1, min(v0 + g * (zc - z0), cap), 0.0))\n        for za, zb, va, gg in segs:\n            d = np.clip(z - za, 0.0, zb - za)\n            t += (2.0 / gg) * np.log1p(gg * d / va) if gg > 1e-9 else 2.0 * d / va\n    return t\n\n\ndef make_td_samples(n, rng, zmin=50.0, zmax=(NZ - 1) * DH, noise_ms=2.0):\n    """n independent 1-D columns, one (depth, TWT) sample from each -> dict of arrays.\n    noise_ms = standard deviation of the TWT \'picking\' error added to mimic checkshot data."""\n    depth = np.empty(n); twt = np.empty(n); v0 = np.empty(n); nl = np.empty(n, dtype=int)\n    t500 = np.empty(n)                                      # shallow well tie: TWT at 500 m depth\n    for i in range(n):\n        col = sample_layer_column(rng, zmax)\n        depth[i] = rng.uniform(zmin, zmax)\n        twt[i] = column_twt(col, depth[i]) * 1000.0         # ms\n        v0[i] = col["vtop"][0]; nl[i] = col["nl"]\n        t500[i] = column_twt(col, 500.0) * 1000.0\n    obs = np.maximum(twt + rng.normal(0.0, noise_ms, n), 1.0)\n    t500 = t500 + rng.normal(0.0, noise_ms, n)\n    return dict(depth_m=depth, twt_true_ms=twt, twt_ms=obs, v0_m_s=v0, twt500_ms=t500,\n                n_layers=nl, vavg_m_s=2.0 * depth / (twt / 1000.0))\n\n\ndef make_velocity_model(rng, nz=NZ, nx=NX, dh=DH, salt=None, fault=None, return_info=False):\n    """2-D velocity model (nz x nx, m/s): <=4 layers, V(z)=V_top+k(z-z_top) in every layer."""\n    zmax = (nz - 1) * dh\n    xs, zs = np.arange(nx) * dh, np.arange(nz) * dh\n    col = sample_layer_column(rng, zmax)\n    nl = col["nl"]\n    # --- conformable interfaces: shared regional structure + small independent undulation\n    base = rng.uniform(-0.06, 0.06) * (xs - xs.mean())                    # regional dip (<= 3.4 deg)\n    for _ in range(2):\n        base += rng.uniform(0, 0.04) * zmax * np.sin(\n            2 * np.pi * xs / (rng.uniform(0.5, 2.0) * xs[-1]) + rng.uniform(0, 2 * np.pi))\n    tops = np.zeros((nl - 1, nx))\n    for k in range(nl - 1):\n        wiggle = rng.uniform(0, 0.015) * zmax * np.sin(\n            2 * np.pi * xs / (rng.uniform(0.3, 1.0) * xs[-1]) + rng.uniform(0, 2 * np.pi))\n        tops[k] = col["tops"][k] + rng.uniform(0.7, 1.3) * base + wiggle\n        tops[k] = np.clip(tops[k], (k + 1) * MIN_THICK_2D, zmax - (nl - 1 - k) * MIN_THICK_2D)\n        if k > 0:                                                         # keep order + min thickness\n            tops[k] = np.maximum(tops[k], tops[k - 1] + MIN_THICK_2D)\n    # --- optional normal fault: hanging wall (right side) is shifted down by `throw`\n    X, Z = np.meshgrid(xs, zs)\n    has_fault = (rng.random() < FAULT_PROB) if fault is None else bool(fault)\n    Zeff = Z\n    if has_fault:\n        x0 = rng.uniform(0.25, 0.75) * xs[-1]\n        dip = np.deg2rad(rng.uniform(60, 80))\n        throw = rng.uniform(40, 160)\n        Zeff = np.clip(Z - throw * (X - x0 - Z / np.tan(dip) >= 0), 0, None)\n    # --- layer index + compaction gradient inside each layer\n    idx = (Zeff[:, None, :] >= tops[None, :, :]).sum(axis=1)\n    tops_ext = np.vstack([np.zeros(nx), tops])\n    ztop = np.take_along_axis(tops_ext, idx, axis=0)\n    v = np.minimum(col["vtop"][idx] + col["grad"][idx] * (Zeff - ztop), col["cap"][idx])\n    v = gaussian_filter(v, sigma=1.0)                                     # smooth interfaces (~20 m)\n    # --- weak lateral heterogeneity (facies / porosity changes), 1-3 % rms\n    f = gaussian_filter(rng.standard_normal((nz, nx)), sigma=(12, 25))\n    v = v * (1.0 + rng.uniform(0.01, 0.03) * f / (f.std() + 1e-9))\n    # --- optional salt body (off by default)\n    has_salt = (rng.random() < SALT_PROB) if salt is None else bool(salt)\n    if has_salt:\n        cx = rng.uniform(0.2, 0.8) * xs[-1]\n        if rng.random() < 0.4:                                            # dome rising from the bottom\n            w = rng.uniform(0.15, 0.45) * xs[-1]; h = rng.uniform(0.3, 0.8) * zmax\n            p = rng.uniform(1.0, 2.0)\n            ztop_s = zmax - h * np.clip(1 - ((xs - cx) / w) ** 2, 0, None) ** p\n            mask = (Z >= ztop_s[None, :]) & (np.abs(X - cx) < w)\n        else:                                                             # blob with Fourier boundary\n            cz = rng.uniform(0.35, 0.85) * zmax\n            rx, rz = rng.uniform(0.1, 0.35) * xs[-1], rng.uniform(0.08, 0.25) * zmax\n            th = np.arctan2((Z - cz) / rz, (X - cx) / rx)\n            rr = np.hypot((X - cx) / rx, (Z - cz) / rz)\n            bound = np.ones_like(th)\n            for k in range(2, 6):\n                bound += rng.uniform(-0.18, 0.18) / (k / 2) * np.cos(k * th + rng.uniform(0, 6.28))\n            mask = rr < bound\n        v = np.where(mask, SALT_VEL, v)\n    v = np.clip(v, V_MIN, V_MAX).astype(np.float32)\n    if return_info:\n        return v, dict(n_layers=nl, lithology=col["lith"], v_top=col["vtop"].tolist(),\n                       gradient=col["grad"].tolist(), fault=bool(has_fault), salt=bool(has_salt),\n                       n_layers_in_model=int(len(np.unique(idx))), boundaries_m=tops.tolist(),\n                       layer_labels=idx.astype(np.uint8),\n                       minimum_thickness_m=float(np.min(np.diff(np.vstack([np.zeros(nx),tops,np.full(nx,zmax)]),axis=0))))\n    return v\nclass Modeler:\n\n    def __init__(self, shots, nt, ds, device, nz=NZ, nx=NX, dh=DH, dt=DT, fpeak=FPEAK, pad=40, damp_a=0.01):\n        self.S, self.nt, self.ds, self.dev = (shots, nt, ds, device)\n        self.nz, self.nx, self.dh, self.dt, self.pad = (nz, nx, dh, dt, pad)\n        c = np.array([-205 / 72, 8 / 5, -1 / 5, 8 / 315, -1 / 560]) / dh ** 2\n        k = torch.tensor(np.concatenate([c[:0:-1], c]), dtype=torch.float32, device=device)\n        self.kx, self.kz = (k.view(1, 1, 1, 9), k.view(1, 1, 9, 1))\n        self.Zp, self.Xp = (nz + pad, nx + 2 * pad)\n        fx = np.ones(self.Xp)\n        for i in range(pad):\n            f = np.exp(-(damp_a * (pad - i)) ** 2)\n            fx[i] = f\n            fx[self.Xp - 1 - i] = f\n        fz = np.ones(self.Zp)\n        for i in range(pad):\n            fz[self.Zp - 1 - i] = np.exp(-(damp_a * (pad - i)) ** 2)\n        self.damp = torch.tensor(fz[:, None] * fx[None, :], dtype=torch.float32, device=device).view(1, 1, self.Zp, self.Xp)\n        t = np.arange(nt) * dt\n        a = (np.pi * fpeak * (t - 1.0 / fpeak)) ** 2\n        self.wav = torch.tensor((1 - 2 * a) * np.exp(-a), dtype=torch.float32, device=device)\n        self.src_x = np.round(np.linspace(0, nx - 1, shots)).astype(int)\n        mask = torch.zeros(shots, 1, self.Zp, self.Xp, device=device)\n        for s, x in enumerate(self.src_x):\n            mask[s, 0, 1, pad + x] = 1.0 / dh ** 2\n        self.src_mask = mask\n\n    def pad_vel(self, v):\n        return F.pad(v.view(1, 1, self.nz, self.nx), (self.pad, self.pad, 0, self.pad), mode=\'replicate\')\n\n    def _lap(self, p):\n        return F.conv2d(p, self.kx, padding=(0, 4)) + F.conv2d(p, self.kz, padding=(4, 0))\n\n    def _chunk(self, vdt2, mask, p0, p1, it0, it1):\n        rec = []\n        for it in range(it0, it1):\n            if it % 20 == 0:\n                check_budget(\'wave propagation\')\n            p2 = 2 * p1 - p0 + vdt2 * (self._lap(p1) + mask * self.wav[it])\n            p0, p1 = (p1 * self.damp, p2 * self.damp)\n            if it % self.ds == 0:\n                rec.append(p1[:, 0, 1, self.pad:self.pad + self.nx])\n        return (p0, p1, torch.stack(rec, 1))\n\n    def simulate(self, v, shot_ids=None, grad=False):\n        """v: (nz,nx) tensor in m/s -> seismograms (n_shots, n_time_samples, nx)."""\n        sid = list(range(self.S)) if shot_ids is None else list(shot_ids)\n        vdt2 = (self.pad_vel(v) * self.dt) ** 2\n        mask = self.src_mask[sid]\n        p0 = torch.zeros(len(sid), 1, self.Zp, self.Xp, device=self.dev)\n        p1 = torch.zeros_like(p0)\n        recs, step = ([], self.ds * 10)\n        for it0 in range(0, self.nt, step):\n            it1 = min(self.nt, it0 + step)\n            if grad:\n                p0, p1, r = checkpoint(self._chunk, vdt2, mask, p0, p1, it0, it1, use_reentrant=False)\n            else:\n                p0, p1, r = self._chunk(vdt2, mask, p0, p1, it0, it1)\n            recs.append(r)\n        return torch.cat(recs, 1)\ndef dconv(i, o):\n    return nn.Sequential(nn.Conv2d(i, o, 3, padding=1), nn.BatchNorm2d(o), nn.ReLU(inplace=True), nn.Conv2d(o, o, 3, padding=1), nn.BatchNorm2d(o), nn.ReLU(inplace=True))\n\nclass FCNVMB(nn.Module):\n\n    def __init__(self, in_ch, out_hw=(NZ, NX), base=64, depth=4):\n        super().__init__()\n        self.out_hw, self.depth = (out_hw, depth)\n        ch = [base * 2 ** i for i in range(depth + 1)]\n        self.enc = nn.ModuleList([dconv(in_ch, ch[0])] + [dconv(ch[i], ch[i + 1]) for i in range(depth)])\n        self.up = nn.ModuleList([nn.ConvTranspose2d(ch[i + 1], ch[i], 2, stride=2) for i in reversed(range(depth))])\n        self.dec = nn.ModuleList([dconv(ch[i] * 2, ch[i]) for i in reversed(range(depth))])\n        self.out = nn.Conv2d(ch[0], 1, 1)\n\n    def forward(self, x):\n        T, X = x.shape[-2:]\n        m = 2 ** self.depth\n        x = F.pad(x, (0, -X % m, 0, -T % m))\n        skips = []\n        for i, blk in enumerate(self.enc):\n            x = blk(x)\n            if i < self.depth:\n                skips.append(x)\n                x = F.max_pool2d(x, 2)\n        for up, dec in zip(self.up, self.dec):\n            x = dec(torch.cat([up(x), skips.pop()], 1))\n        x = self.out(x)\n        nz, nx = self.out_hw\n        if x.shape[-2] >= nz and x.shape[-1] >= nx:\n            return x[..., :nz, :nx]\n        return F.interpolate(x, size=(nz, nx), mode=\'bilinear\', align_corners=False)'

def runtime(c,device="cpu"):
    env=dict(np=np,torch=torch,nn=nn,F=F,gaussian_filter=gaussian_filter,checkpoint=checkpoint,
             NZ=c["nz"],NX=c["nx"],DH=c["dx_m"],DT=c["dt_sim_s"],FPEAK=c["source_hz"],
             DEV=torch.device(device),SEED=c.get("seed",0),QUICK_TEST=c.get("quick_test",True),
             check_budget=lambda *args:None)
    exec(SOURCE,env)
    return env
